for id,name,prep,use,steps in data:
 for i,text in overrides.get(id,{}).items():
  a,b,_=steps[i];steps[i]=(a,b,text)
rows={}
for id,name,prep,use,steps in data:
 classic=name in ['Herbalism','Skinning']
 slug=name.lower().replace(' ','-')
 source=('https://www.wow-professions.com/classic/'+slug+'-leveling-guide-classic-wow') if classic else 'https://www.wow-professions.com/forever/'+slug+'-leveling-guide'
 rows[id]=dict(name=name,prep=prep,use=use,source=source,coverage='Classic-derived heuristics; Forever route unverified' if classic else 'Forever guide summary; detailed recipe coverage partial; later content untested',training='Check trainer/book requirements in client before travel; displayed trained cap takes priority. Production ranks commonly unlock at skill 50/125/200 and levels 10/20/35; secondary/gathering exceptions apply.',steps=[dict(zip(['from','to','text'],r)) for r in steps])
Path('RuinousForeverPlanner/ProfessionData.lua').write_text('local _,P=...\nP.ProfessionOrder='+lua([r[0] for r in data])+'\nP.ProfessionData='+lua(rows)+'\n',encoding='utf8')
Path('research/professions.json').write_text(json.dumps({'reviewed':'2026-10-21','liveTested':False,'guides':rows},indent=2))
